-- ── TRANSIÇÕES AMBÍGUAS (225 linhas) ──
-- Pares de transições opostas a menos de 10 segundos no mesmo equipamento.
-- Bomba não liga e desliga em 2 segundos; sem o payload cru não há como dizer
-- qual leitura era o estado real. Permanecem OPERACIONAIS — removê-las rompe a
-- sequência e a invariante sobe de 0 para 3 — mas ficam marcadas: não são
-- equivalentes a transição comprovada. action e occurred_at intactos.
UPDATE public.automation_log
   SET details = coalesce(details,'{}'::jsonb) || jsonb_build_object(
                   'uncertain_transition', true,
                   'uncertainty_reason', 'transicao_oposta_em_menos_de_10s_no_mesmo_equipamento')
