    RAISE EXCEPTION 'abortado: % linhas alvo continuam operacionais', v_pend;
  END IF;

  SELECT count(*) INTO v_admin FROM public.automation_log
   WHERE actor_label = 'Admin Renov' AND id = ANY(ARRAY[
'83d6ef44-a856-4e70-a469-b98b78f603b8','946f78b5-9b37-4c15-a566-e28a7e0aba2d','96689a1d-5c95-4883-b88c-ea77a50007ad','9bef34b9-0a98-41e5-b63c-5ef9d6945177'
]::uuid[]);
  IF v_admin <> 0 THEN
    RAISE EXCEPTION 'abortado: % linhas de autoria nao corrigidas', v_admin;
  END IF;

  WITH fluxo AS (
    SELECT al.equipment_id,
           CASE WHEN al.action IN ('turn_on','pump_on') THEN 1 ELSE 0 END AS est,
           lag(CASE WHEN al.action IN ('turn_on','pump_on') THEN 1 ELSE 0 END)
             OVER (PARTITION BY al.equipment_id ORDER BY al.occurred_at, al.created_at, al.id) AS ant
      FROM public.automation_log al JOIN public.farms f ON f.id = al.farm_id
     WHERE al.noise_reason IS NULL
       AND al.action IN ('turn_on','turn_off','pump_on','pump_off')
       AND al.occurred_at < timestamptz '2026-09-22 18:28:03.139486+00'
       AND f.name IN ('Pérola','Fazenda Sykue','Semear','Fazenda Terra Norte','Fazenda Sossego'))
  SELECT count(*) INTO v_viol FROM fluxo WHERE ant IS NOT NULL AND est = ant;
  IF v_viol <> 0 THEN
    RAISE EXCEPTION 'abortado: % repeticoes de estado sobraram no historico', v_viol;
  END IF;

  RAISE NOTICE 'saneamento OK: 0 pendentes, 0 autorias erradas, 0 repeticoes';
END $$;

COMMIT;

